const { logger } = require('../utils/logger'); // Assuming we have a structured logger utility

/**
 * RateLimiter Class
 * Encapsulates the logic for the sliding window rate limiter.
 * 
 * @param {Object} options
 * @param {Function} options.clock - A function that returns the current timestamp in ms. Injectable for testing.
 * @param {Object} options.store - An object implementing get(ip), set(ip, data), and delete(ip). Injectable for testing.
 * @param {number} options.windowMs - The window size in milliseconds.
 * @param {number} options.maxRequests - The max number of requests allowed in the window.
 */
class RateLimiter {
  constructor({ clock, store, windowMs, maxRequests }) {
    if (typeof clock !== 'function') throw new Error('clock must be a function');
    if (!store || typeof store.get !== 'function' || typeof store.set !== 'function') {
      throw new Error('store must be an object with get and set methods');
    }

    // Config Validation: Fail fast if invalid
    if (!Number.isInteger(maxRequests) || maxRequests < 1) {
      throw new Error(`RATE_LIMIT_MAX_REQUESTS must be a positive integer. Received: ${maxRequests}`);
    }
    if (!Number.isInteger(windowMs) || windowMs < 1) {
      throw new Error(`RATE_LIMIT_WINDOW_MS must be a positive integer. Received: ${windowMs}`);
    }

    this.clock = clock;
    this.store = store;
    this.windowMs = windowMs;
    this.maxRequests = maxRequests;
